// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, bytes memory encodedParameters, address ownedBy) public {
        vm.assume(caller != address(0));
        vm.assume(ownedBy != address(0));

        // Set up program operator
        vm.prank(caller);
        c.initialize();

        // Set required addresses
        address roundImpl = address(0x1234);
        vm.prank(caller);
        c.updateRoundImplementation(payable(roundImpl));

        address alloSettings = address(0x5678);
        vm.prank(caller);
        c.updateAlloSettings(alloSettings);

        // Register caller as program operator
        vm.prank(caller);
        // Cannot directly set programOperators, so fund via create

        // Now test: after initialize, owner should be the caller
        assertTrue(c.owner() == caller);
    }
}

